          "content": {
            "imageUrl": "https://mcuquzgpaeoqskesgcnx.supabase.co/storage/v1/object/public/c/ChatGPT%20Image%20Sep%2021,%202025,%2001_16_04%20PM%20(1).png"
          },
          "imageUrl": "https://mcuquzgpaeoqskesgcnx.supabase.co/storage/v1/object/public/c/ChatGPT%20Image%20Sep%2021,%202025,%2001_16_04%20PM%20(1).png",
